        angles[ 4] := 24 * Pi/180; Colors[ 4] := 'FF9600'; // Orange     
        angles[ 5] := 27 * Pi/180; Colors[ 5] := 'DC0000'; // Red        
        angles[ 6] := 33 * Pi/180; Colors[ 6] := '00FF00'; // Lime       
        angles[ 7] := 36 * Pi/180; Colors[ 7] := '800080'; // Purple     
        angles[ 8] := 39 * Pi/180; Colors[ 8] := '808000'; // Olive      
        angles[ 9] := 42 * Pi/180; Colors[ 9] := '00FFFF'; // Cyan       
